import{_ as t,o as a,c as n,a7 as i}from"./chunks/framework.SHqkCsSs.js";const u=JSON.parse('{"title":"Prepare Your Development Environment","description":"The planned Feluqa dev:init setup for Rust, target-specific tools, and the recommended Zed editor.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version English est affichée.","sidebarTitle":"Setup","icon":"wrench","title":"Prepare Your Development Environment","description":"The planned Feluqa dev:init setup for Rust, target-specific tools, and the recommended Zed editor.","summary":"Describes the planned feluqa dev:init flow for installing Rust and target-specific dependencies based on the selected application profile. It covers editor choice, recommends Zed while noting other Rust Analyzer editors, and links the setup stage to the first project tutorial without presenting the planned automation as implemented.","weight":2,"tags":["feluqa","getting-started","rust","zed","setup"],"date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","status":"Exploring","draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"},"search":false},"headers":[],"relativePath":"fr/get-started/installation.md","filePath":"fr/get-started/installation.md"}'),s={name:"fr/get-started/installation.md"};function r(o,e,l,d,p,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="prepare-your-development-environment" tabindex="-1">Prepare Your Development Environment <a class="header-anchor" href="#prepare-your-development-environment" aria-label="Permalink to &quot;Prepare Your Development Environment&quot;">​</a></h1><blockquote><p>This is part two of <a href="/fr/learn/create-your-first-application">Create Your First Application</a>.</p></blockquote><h2 id="prepare-the-development-environment" tabindex="-1">Prepare the development environment <a class="header-anchor" href="#prepare-the-development-environment" aria-label="Permalink to &quot;Prepare the development environment&quot;">​</a></h2><p>The interactive <code>feluqa dev:init</code> command is intended to prepare the machine for the application and target profiles selected in the previous step. It will inspect the host, identify the required tools, install missing supported dependencies, and verify the result. It should avoid installing tools for targets the project does not use.</p><p>Depending on the selected application, setup may include:</p><ul><li><strong>Rust.</strong> Install Rust with <code>rustup</code> when needed and select the stable toolchain. Install only the target triples required by the selected builds; for example, a browser WebAssembly build may need <code>wasm320-unknown-unknown</code>.</li><li><strong>Feluqa tooling.</strong> Install or locate the Feluqa CLI and verify that it can create and build the selected application type.</li><li><strong>Host dependencies.</strong> Detect and install operating-system packages needed by the selected runtimes. A command-line or server project should not install graphical desktop libraries. Native desktop targets may need a platform UI toolkit; mobile targets require their platform SDKs and build tools.</li><li><strong>Platform-specific setup.</strong> On macOS, iOS builds require Apple&#39;s Xcode and SDKs. Android builds require the Android SDK and NDK. Linux and Windows desktop builds may need additional native libraries or toolchains. WSL setup depends on whether the selected target needs Linux graphics or device access.</li></ul><p><code>dev:init</code> should finish with a clear report of installed tools, selected Rust targets, and any requirement that still needs a manual step, such as accepting a platform SDK license. A developer can then build and run a minimal project before adding application code.</p><p>The stable Rust compiler is the expected default. If Rust is already managed with <code>rustup</code>, the equivalent setup includes commands such as:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wasm320-unknown-unknown</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # only when the selected build needs it</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The <a href="https://doc.rust-lang.org/book/" target="_blank" rel="noreferrer">Rust Book</a> is a useful way to learn Rust. It is recommended background, not a prerequisite for trying the first Feluqa project. The walkthrough introduces Rust concepts as they appear and keeps async code, lifetimes, and ownership details tied to the examples that need them.</p><h2 id="pick-an-editor" tabindex="-1">Pick an editor <a class="header-anchor" href="#pick-an-editor" aria-label="Permalink to &quot;Pick an editor&quot;">​</a></h2><p><strong>Zed is the recommended editor for Feluqa projects.</strong> It is fast, has built-in Rust Analyzer support, and can use Feluqa&#39;s editor extension for <code>.view.rs</code> templates. The extension provides template highlighting and Rust injections; Rust Analyzer provides Rust navigation and analysis, while the Feluqa build reports template compiler errors.</p><p>The Feluqa Zed extension is not yet available through a user-facing install channel. The planned CLI command is <code>feluqa support:ide zed</code>; both the command and extension distribution still need to be implemented. Until then, Zed&#39;s Rust support is available, while Feluqa-specific <code>.view.rs</code> highlighting is not available to application users. Other editors such as VS Code, Emacs, and Vim can be used with Rust Analyzer; <code>.view.rs</code> support depends on an editor extension being available for that editor.</p><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><p>With the machine ready, continue to <a href="/fr/get-started/directory-structure/cli-structure">How a Feluqa CLI is structured</a>.</p>`,15)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
